        vm.deal(actor2, amount2);
        vm.prank(actor2);
        bool ok2;
        try c.addToBalance{value: amount2}() { ok2 = true; } catch { ok2 = false; }
        assertTrue(ok2, "contract must not stay locked after a successful deposit");
    }
}

