pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reent attacker;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 extra) public {
        amount = bound(amount, 1 ether, 10 ether);
        extra = bound(extra, amount, 100 ether);

        attacker = new Reent(c);
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.addToBalance{value: amount}();
        vm.deal(address(c), extra);

        uint256 before = address(c).balance;
        uint256 bal0 = c.getBalance(address(attacker));

        bool ok;
        try attacker.pull() { ok = true; } catch { ok = false; }

        assertTrue(
            !ok || (c.getBalance(address(attacker)) == 0 && address(c).balance == before - bal0),
            "a successful withdrawal pays exactly the recorded balance and zeroes it"
        );
    }
}

contract Reent {
    C c;
    constructor(C _c) { c = _c; }
    function deposit() external payable { c.addToBalance{value: msg.value}(); }
    function pull() external { c.withdrawBalance(); }
    receive() external payable {
        // re-enter; tolerate failure of the inner low-level call
        try c.withdrawBalance() {} catch {}
    }
}

